try{$c=srn_config();$report=srn_tx($c,function(&$s)use($c){$now=time();$today=(new DateTimeImmutable('now',new DateTimeZone('Europe/Amsterdam')))->format('Y-m-d');$removed=0;$queued=0;$orphaned=[];foreach(glob($c['dir'].'/files/*.bin')?:[]as$file){$id=basename($file,'.bin');if(!is_link($file)&&preg_match('/^[a-f0-9]{32}$/D',$id)&&!isset($s['files'][$id])&&filemtime($file)<$now-3600)$orphaned[]=$id;}foreach($s['leads']as$id=>$l){$age=$now-strtotime($l['updated']);if(($l['status']==='pending'&&$age>86400)||(in_array($l['status'],['lost','invalid','withdrawn'],true)&&$age>90*86400)){unset($s['leads'][$id]);$removed++;}}foreach($s['outbox']as$id=>$m)if($m['created']<$now-7*86400){unset($s['outbox'][$id]);$removed++;}foreach($s['reminders']as$id=>$r){if($r['date']<date('Y-m-d',$now-7*86400)){unset($s['reminders'][$id]);continue;}if($r['date']<=$today&&!$r['sent']&&isset($s['accounts'][$r['owner']],$s['projects'][$r['project']])){srn_queue($s,$s['accounts'][$r['owner']]['email'],'reminder','Je hebt zelf een herinnering ingesteld. Open Mijn plan en controleer je volgende stap en de actuele officiële voorwaarden.'."\n".$c['origin'].'/mijn-plan/','reminder:'.$id,['reminder'=>$id]);$s['reminders'][$id]['sent']=true;$queued++;}}$s['audit']=array_values(array_filter($s['audit'],fn($a)=>strtotime($a['at'])>$now-90*86400));return ['removed'=>$removed,'orphans_scheduled'=>count($orphaned),'_purge'=>$orphaned,'reminders_queued'=>$queued,'account_inactivity'=>'Geen automatische accountverwijdering in deze beta; vooraf retentiebeleid vaststellen.'];});echo json_encode($report,JSON_PRETTY_PRINT)."\n";}catch(Throwable){fwrite(STDERR,"Onderhoud mislukt; geen succesvolle run bevestigd.\n");exit(1);}
